def _parse_reduction(reduction):
    """ATen returns the unreduced loss for any value that is not mean/sum."""
    if isinstance(reduction, str):
        key = reduction.lower()
        if key == "none":
            return _NONE
        if key == "mean":
            return _MEAN
        if key == "sum":
            return _SUM
        raise ValueError("Invalid reduction: {}".format(reduction))
    value = int(reduction)
    if value == _MEAN:
        return _MEAN
    if value == _SUM:
        return _SUM
    return _NONE


