@triton.jit(do_not_specialize=["n"])
def _pnll_bwd_kernel(
    in_ptr,
    t_ptr,
    gout_ptr,
    gi_ptr,
    gt_ptr,
    n,
    eps,
    SHAPE: tl.constexpr,
    IS: tl.constexpr,
    TS: tl.constexpr,
    GIS: tl.constexpr,
    GTS: tl.constexpr,
    GOS: tl.constexpr,
    NDIM: tl.constexpr,
    CONTIG: tl.constexpr,
    LOG_INPUT: tl.constexpr,
    FULL: tl.constexpr,
    FP64: tl.constexpr,
    GSCALAR: tl.constexpr,
    MEAN: tl.constexpr,
    NEED_GI: tl.constexpr,
    NEED_GT: tl.constexpr,
    GI_ACC: tl.constexpr,
    GT_ACC: tl.constexpr,
    GI_HALF: tl.constexpr,
    GT_HALF: tl.constexpr,
    GI_BF16: tl.constexpr,
    GT_BF16: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    if CONTIG:
        i_off = offs
        t_off = offs
        gi_off = offs
        gt_off = offs
        go_off = offs
    else:
        idx = offs
        i_off = offs * 0
        t_off = offs * 0
        gi_off = offs * 0
        gt_off = offs * 0
        go_off = offs * 0
        for d in tl.static_range(NDIM - 1, -1, -1):
            size = SHAPE[d]
            q = idx // size
            r = idx - q * size
            i_off += r * IS[d]
            t_off += r * TS[d]
            gi_off += r * GIS[d]
            gt_off += r * GTS[d]
            go_off += r * GOS[d]
            idx = q
    x = tl.load(in_ptr + i_off, mask=mask, other=0)
    y = tl.load(t_ptr + t_off, mask=mask, other=0)
    if FP64:
        xf = x.to(tl.float64)
        yf = y.to(tl.float64)
        ev = eps.to(tl.float64)
    else:
        xf = x.to(tl.float32)
        yf = y.to(tl.float32)
        ev = eps.to(tl.float32)
    if LOG_INPUT:
        dxi = tl.exp(xf) - yf
        dti = -xf
    else:
        den = xf + ev
        dxi = 1.0 - yf / den
        dti = -tl.log(den)
    if FULL:
        dti = dti + tl.where(yf > 1.0, tl.log(yf) + 0.5 / yf, 0.0)
    if GSCALAR:
        gv = tl.load(gout_ptr)
        if MEAN:
            if FP64:
                gv = gv.to(tl.float64) / n.to(tl.float64)
            else:
                gv = gv.to(tl.float32) / n.to(tl.float32)
        else:
            if FP64:
                gv = gv.to(tl.float64)
            else:
                gv = gv.to(tl.float32)
    else:
        gv = tl.load(gout_ptr + go_off, mask=mask, other=0)
        if FP64:
            gv = gv.to(tl.float64)
        else:
            gv = gv.to(tl.float32)
    dxi = dxi * gv
    dti = dti * gv
    if NEED_GI:
        if GI_ACC:
            tl.atomic_add(gi_ptr + gi_off, _cast_grad(dxi, GI_HALF, GI_BF16), mask=mask)
        else:
            tl.store(gi_ptr + gi_off, dxi, mask=mask)
    if NEED_GT:
        if GT_ACC:
            tl.atomic_add(gt_ptr + gt_off, _cast_grad(dti, GT_HALF, GT_BF16), mask=mask)
        else:
            tl.store(gt_ptr + gt_off, dti, mask=mask)


