def _forward(input, target, log_input, full, eps, red):
    dtype = _result_dtype(input, target)
    is_cplx = dtype.is_complex
    fp64 = dtype == _F64 or dtype == torch.complex128

    out_shape, istr, tstr = _broadcast_dims(
        input.shape, input.stride(), target.shape, target.stride()
    )
    n = 1
    for size in out_shape:
        n *= size

    dims = _collapse(out_shape, istr, tstr)
    shape_t = tuple(d[0] for d in dims)
    is_t = tuple(d[1] for d in dims)
    ts_t = tuple(d[2] for d in dims)
    ndim = len(dims)
    contig = ndim == 1 and shape_t[0] == n and is_t[0] == 1 and ts_t[0] == 1

    eps_v = _eps_scalar(eps, dtype)

    in_cplx = input.is_complex()
    tgt_cplx = target.is_complex()
    if in_cplx:
        in_v, in_conj = _real_view(input)
    else:
        in_v, in_conj = input, False
    if tgt_cplx:
        t_v, tgt_conj = _real_view(target)
    else:
        t_v, tgt_conj = target, False
    common = dict(
        SHAPE=shape_t,
        IS=is_t,
        TS=ts_t,
        NDIM=ndim,
        CONTIG=contig,
        LOG_INPUT=log_input,
        FULL=full,
        FP64=fp64,
        CPLX=is_cplx,
        IN_REAL=not in_cplx,
        TGT_REAL=not tgt_cplx,
        IN_CONJ=in_conj,
        TGT_CONJ=tgt_conj,
    )

    if red == _NONE:
        out = torch.empty(out_shape, dtype=dtype, device=input.device)
        if n == 0:
            return out
        out_v = torch.view_as_real(out) if is_cplx else out
        grid = (triton.cdiv(n, _BLOCK_ELEM),)
        _pnll_none_kernel[grid](
            in_v,
            t_v,
            out_v,
            n,
            eps_v,
            **common,
            MASKED=(n % _BLOCK_ELEM != 0),
            BLOCK=_BLOCK_ELEM,
            num_warps=4,
        )
        return out

    out = torch.empty((), dtype=dtype, device=input.device)
    out_v = torch.view_as_real(out) if is_cplx else out
    mean = red == _MEAN
    if n <= _TINY_MAX:
        _pnll_tiny_kernel[(1,)](
            in_v,
            t_v,
            out_v,
            n,
            eps_v,
            **common,
            MASKED=(n % _BLOCK_TINY != 0),
            MEAN=mean,
            BLOCK=_BLOCK_TINY,
            num_warps=4,
        )
        return out

    nprog = min(triton.cdiv(n, _BLOCK_RED), _MAX_PROG)
    acc_dtype = _F64 if fp64 else _F32
    part = torch.empty(
        nprog * (2 if is_cplx else 1), dtype=acc_dtype, device=input.device
    )
    _pnll_partial_kernel[(nprog,)](
        in_v,
        t_v,
        part,
        n,
        eps_v,
        **common,
        MASKED=(n % _BLOCK_RED != 0),
        BLOCK=_BLOCK_RED,
        num_warps=8,
    )
    _pnll_final_kernel[(1,)](
        part,
        out_v,
        nprog,
        n,
        MEAN=mean,
        FP64=fp64,
        CPLX=is_cplx,
        MASKED=(nprog % _BLOCK_FINAL != 0),
        BLOCK=_BLOCK_FINAL,
        num_warps=4,
    )
    return out


def _backward(input, target, gout, log_input, full, eps, red, need_i, need_t):
    fp64 = _result_dtype(input, target) == _F64
    out_shape, istr, tstr = _broadcast_dims(
        input.shape, input.stride(), target.shape, target.stride()
    )
    n = 1
    for size in out_shape:
        n *= size

    gi = (
        torch.zeros(input.shape, dtype=input.dtype, device=input.device)
        if need_i
        else None
    )
    gt = (
        torch.zeros(target.shape, dtype=target.dtype, device=target.device)
        if need_t
        else None
    )
    if n == 0 or not (need_i or need_t):
        return gi, gt

    gi_full = _contig_strides_to(input.shape, out_shape)
    gt_full = _contig_strides_to(target.shape, out_shape)
    go_full = _strides_to(gout.shape, gout.stride(), out_shape)
    sizes, (is_t, ts_t, gi_s, gt_s, go_s) = _collapse_multi(
        out_shape, [istr, tstr, gi_full, gt_full, go_full]
    )
    ndim = len(sizes)
    gi_acc = need_i and _broadcasts(input.shape, out_shape)
    gt_acc = need_t and _broadcasts(target.shape, out_shape)
    one = (1,) * ndim
    contig = (
        ndim == 1
        and sizes[0] == n
        and is_t == one
        and ts_t == one
        and gi_s == one
        and gt_s == one
        and go_s == one
    )

    eps_v = _eps_scalar(eps, _result_dtype(input, target))
    grid = (triton.cdiv(n, _BLOCK_ELEM),)
    _pnll_bwd_kernel[grid](
        input,
        target,
        gout,
        gi if need_i else input,
        gt if need_t else target,
        n,
        eps_v,
        SHAPE=sizes,
        IS=is_t,
        TS=ts_t,
        GIS=gi_s,
        GTS=gt_s,
        GOS=go_s,
        NDIM=ndim,
        CONTIG=contig,
        LOG_INPUT=log_input,
        FULL=full,
        FP64=fp64,
        GSCALAR=(red != _NONE),
        MEAN=(red == _MEAN),
        NEED_GI=need_i,
        NEED_GT=need_t,
        GI_ACC=gi_acc,
        GT_ACC=gt_acc,
        GI_HALF=(need_i and input.dtype == _F16),
        GT_HALF=(need_t and target.dtype == _F16),
        GI_BF16=(need_i and input.dtype == _BF16),
        GT_BF16=(need_t and target.dtype == _BF16),
        BLOCK=_BLOCK_ELEM,
        num_warps=4,
    )
    return gi, gt


class _PoissonNLLLoss(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, target, log_input, full, eps, reduction):
        out = _forward(input, target, log_input, full, eps, reduction)
        ctx.save_for_backward(input, target)
        ctx.pnll = (log_input, full, eps, reduction)
        return out

    @staticmethod
    def backward(ctx, grad_out):
        input, target = ctx.saved_tensors
        log_input, full, eps, reduction = ctx.pnll
        gi, gt = _backward(
            input,
            target,
            grad_out,
            log_input,
            full,
            eps,
            reduction,
            ctx.needs_input_grad[0],
            ctx.needs_input_grad[1],
        )
        return gi, gt, None, None, None, None


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------
def poisson_nll_loss(input, target, log_input=True, full=False, eps=1e-8, reduction=1):
    logger.debug("GEMS_THEAD POISSON_NLL_LOSS")
    if input.device != target.device:
        raise RuntimeError("input and target must be on the same device")
    red = _parse_reduction(reduction)
    log_input = bool(log_input)
    full = bool(full)
    if full and target.dtype == torch.bool:
        raise RuntimeError("Subtraction with a bool target is not supported")
    if (not log_input) and input.dtype == torch.bool:
        raise RuntimeError("Subtraction with a bool input is not supported")
    if full and target.is_complex():
        raise RuntimeError("Comparisons with a complex target are not supported")

    needs_grad = (
        torch.is_grad_enabled()
        and (input.requires_grad or target.requires_grad)
        and not input.is_complex()
        and not target.is_complex()
        and input.dtype.is_floating_point
        and target.dtype.is_floating_point
    )
    if needs_grad:
        return _PoissonNLLLoss.apply(input, target, log_input, full, float(eps), red)
    return _forward(input, target, log_input, full, eps, red)
